async function loadPrayerTimes(lat,lon){try{const ts=Math.floor(Date.now()/1000);const r=await fetch('https://api.aladhan.com/v1/timings/'+ts+'?latitude='+encodeURIComponent(lat)+'&longitude='+encodeURIComponent(lon)+'&method=4');if(!r.ok)throw new Error('HTTP '+r.status);const j=await r.json(),t=j.data.timings,n=['Fajr','Dhuhr','Asr','Maghrib','Isha'],ar=['الفجر','الظهر','العصر','المغرب','العشاء'];let box=$('#prayerStatus');box.className='prayer-times-grid';box.innerHTML=n.map((x,i)=>'<div class="prayer-time"><small>'+(state.lang==='ar'?ar[i]:x)+'</small><b>'+t[x]+'</b></div>').join('');const now=new Date(),mins=now.getHours()*60+now.getMinutes();let next=0;for(let i=0;i<n.length;i++){let [h,m]=t[n[i]].split(':').map(Number);if(h*60+m>mins){next=i;break}if(i===n.length-1)next=0}const tomorrow=next===0&&n.every(x=>{const [h,m]=t[x].split(':').map(Number);return h*60+m<=mins});$('#nextPrayer').textContent=(state.lang==='ar'?ar[next]:n[next])+' • '+t[n[next]]+(tomorrow?(state.lang==='ar'?' • غدًا':' • tomorrow'):'');if(j.data.date&&j.data.date.hijri){const h=j.data.date.hijri;box.insertAdjacentHTML('beforeend','<div class="prayer-time"><small>هجري</small><b>'+h.day+' '+h.month.ar+'</b></div>')}}catch(e){$('#prayerStatus').className='notice';$('#prayerStatus').textContent=state.lang==='ar'?'تعذر تحميل المواقيت الآن.':'Prayer times could not be loaded.'}}
