function localizeTextV59(text,lang){if(lang==='ar'||!text)return text;const t=text.trim();const map=lang==='ur'?DYNAMIC_UR:DYNAMIC_EN;const v=map[t];return v?text.replace(t,v):text}
function applyStaticPhrasesV59(lang){$$('[data-l10n]').forEach(e=>{const k=e.dataset.l10n,ar=L10N_AR[k];if(!ar)return;let v;if(lang==='ar')v=ar;else if(lang==='en')v=L10N_EN[k]||PHRASE_EN[ar]||L10N_EN_EXTRA[ar];else v=L10N_UR[k]||PHRASE_UR[ar]||L10N_UR_EXTRA[ar]||L10N_EN[k]||PHRASE_EN[ar]||L10N_EN_EXTRA[ar];if(v)e.textContent=v})}
const _applyLangV59=applyLang;applyLang=function(){_applyLangV59();applyStaticPhrasesV59(state.lang);document.documentElement.dir=state.lang==='en'?'ltr':'rtl';document.body.classList.toggle('lang-ur',state.lang==='ur');document.querySelectorAll('[aria-label]').forEach(el=>{const x=localizeTextV59(el.getAttribute('aria-label'),state.lang);if(x)el.setAttribute('aria-label',x)})};
